                        BackgroundTransparency = 0
                    }):Play()
                end
                
                if backdrop then
                    backdrop.BackgroundTransparency = 1
                    TweenService:Create(backdrop, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {
                        BackgroundTransparency = 0.4
                    }):Play()
                end
            end
            
